module PLL_8x(  
    input wire clk_in,  
    input wire reset,  
    input wire [2:0] freq_select, // Frequency select input for different output frequencies  
    output reg clk_out  
);  
    reg [2:0] counter;  
    reg [2:0] div_counter;  
    reg clk_div;  

    always @(posedge clk_in or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            div_counter <= 0;  
            clk_div <= 0;  
        end else begin  
            if (div_counter == (freq_select + 1)) begin  
                clk_div <= ~clk_div;  
                div_counter <= 0;  
            end else begin  
                div_counter <= div_counter + 1;  
            end  
        end  
    end  

    always @(posedge clk_div or posedge reset) begin  
        if (reset) begin  
            clk_out <= 0;  
        end else begin  
            clk_out <= ~clk_out;  
        end  
    end  
endmodule

