module divider(
    input [3:0] dividend,
    input [3:0] divisor,
    input start,
    input clk,
    output reg [3:0] quotient,
    output reg [3:0] remainder,
    output reg done
);
    reg [3:0] count;
    reg [3:0] temp_dividend;

    always @(posedge clk) begin
        if (start) begin
            if (divisor == 0) begin
                quotient <= 4'b0000; // handling division by zero
                remainder <= dividend; // remainder is the dividend
                done <= 1;
            end else begin
                temp_dividend <= dividend;
                count <= 4'b0000;
                quotient <= 4'b0000;
                done <= 0;
            end
        end else if (!done) begin
            if (temp_dividend >= divisor) begin
                temp_dividend <= temp_dividend - divisor;
                quotient <= quotient + 1;
            end else begin
                remainder <= temp_dividend;
                done <= 1;
            end
        end
    end
endmodule

