module counter_64bit(  
    input clk,  
    input reset,  
    output reg [63:0] count,  
    output reg threshold_reached  
);  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            count <= 64'b0;  
            threshold_reached <= 1'b0;  
        end else begin  
            if (count == 64'd99) begin  
                threshold_reached <= 1'b1;  
            end else begin  
                threshold_reached <= 1'b0;  
            end  
            count <= count + 1;  
        end  
    end  
endmodule

