module fractional_n_pll(
    input wire clk_ref,
    input wire [7:0] fractional_value,
    output reg clk_out
);
    reg [15:0] counter;
    reg [15:0] divider;

    always @(posedge clk_ref) begin
        counter <= counter + 1;
        if (counter >= divider) begin
            clk_out <= ~clk_out;
            counter <= 0;
        end
    end

