module spi_master (
    input wire clk,
    input wire reset,
    input wire start,
    input wire [7:0] data_in,
    input wire miso,
    output reg mosi,
    output reg cs,
    output reg sclk,
    output reg [7:0] data_out,
    output reg done
);

    reg [2:0] state;
    reg [2:0] bit_cnt;
    reg [7:0] shift_reg;

    localparam IDLE = 3'b000;
    localparam SEND = 3'b001;
    localparam RECEIVE = 3'b010;
    localparam FINISH = 3'b011;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            cs <= 1;
            mosi <= 0;
            sclk <= 0;
            done <= 0;
            bit_cnt <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        cs <= 0; // Activate chip select
                        shift_reg <= data_in;
                        bit_cnt <= 7; // Start from the most significant bit
                        state <= SEND;
                        done <= 0;
                    end
                end

                SEND: begin
                    sclk <= 1; // Clock high
                    mosi <= shift_reg[bit_cnt]; // Send bit
                    state <= RECEIVE;
                end

                RECEIVE: begin
                    sclk <= 0; // Clock low
                    if (bit_cnt >= 0) begin
                        data_out[bit_cnt] <= miso; // Read bit
                        bit_cnt <= bit_cnt - 1;
                        state <= SEND; // Go back to sending state
                    end else begin
                        state <= FINISH; // All bits sent
                    end
                end

                FINISH: begin
                    cs <= 1; // Deactivate chip select
                    done <= 1; // Signal that operation is done
                    state <= IDLE; // Go back to idle
                end

                default: state <= IDLE; // Safety
            endcase
        end
    end
endmodule

